INSERT INTO ic_advisors (type, first_name, last_name, organization, email, phone, room, building_id, url, created, created_by, updated, updated_by)
SELECT 'Person', 'Sherry', 'Wilkinson', NULL, 'sjerome@emich.edu', '734.487.4380', 'N101', (SELECT id FROM map_item WHERE discr = 'building' AND name = 'Alexander Music Building'), NULL, NOW(), 'legacy_import', NOW(), 'legacy_import'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ic_advisors WHERE type = 'Person' AND last_name = 'Wilkinson' AND email <=> 'sjerome@emich.edu');
SET @advisor = (SELECT id FROM ic_advisors WHERE type = 'Person' AND last_name = 'Wilkinson' AND email <=> 'sjerome@emich.edu' ORDER BY id LIMIT 1);
UPDATE ic_advisors SET legacy_programs = 'Dance [BA], Dance Minor' WHERE id = @advisor AND legacy_programs IS NULL;
INSERT IGNORE INTO program_advisor (program_id, advisor_id)
SELECT p.id, @advisor FROM program_programs p WHERE (TRIM(p.full_name), p.catalog) IN (('Dance [BA]', 'undergraduate'), ('Dance Minor', 'undergraduate'));

-- person|yang|xyang5@emich.edu
INSERT INTO ic_advisors (type, first_name, last_name, organization, email, phone, room, building_id, url, created, created_by, updated, updated_by)
SELECT 'Person', 'Xining', 'Yang', NULL, 'xyang5@emich.edu', '734.487.8486', '140C', (SELECT id FROM map_item WHERE discr = 'building' AND name = 'Strong Hall'), NULL, NOW(), 'legacy_import', NOW(), 'legacy_import'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM ic_advisors WHERE type = 'Person' AND last_name = 'Yang' AND email <=> 'xyang5@emich.edu');
SET @advisor = (SELECT id FROM ic_advisors WHERE type = 'Person' AND last_name = 'Yang' AND email <=> 'xyang5@emich.edu' ORDER BY id LIMIT 1);
UPDATE ic_advisors SET legacy_programs = 'Geographic Information Systems [M.S.], Geographic Information Systems for Educators [Graduate Certificate], Geographic Information Systems for Professionals [Graduate Certificate], Geographic Information Systems Minor, Geospatial Information Science and Technology [BS]' WHERE id = @advisor AND legacy_programs IS NULL;
INSERT IGNORE INTO program_advisor (program_id, advisor_id)
SELECT p.id, @advisor FROM program_programs p WHERE (TRIM(p.full_name), p.catalog) IN (('Geographic Information Systems [M.S.]', 'graduate'), ('Geographic Information Systems for Educators [Graduate Certificate]', 'graduate'), ('Geographic Information Systems for Professionals [Graduate Certificate]', 'graduate'), ('Geospatial Information Science and Technology [BS]', 'undergraduate'), ('Geographic Information Systems Minor', 'undergraduate'));

COMMIT;

SELECT COUNT(*) AS imported_advisors FROM ic_advisors WHERE created_by = 'legacy_import';
SELECT COUNT(*) AS imported_links FROM program_advisor l JOIN ic_advisors a ON a.id = l.advisor_id WHERE a.created_by = 'legacy_import';
SELECT COUNT(*) AS imported_with_building FROM ic_advisors WHERE created_by = 'legacy_import' AND building_id IS NOT NULL;
SELECT b.name AS missing_building FROM (SELECT 'Alexander Music Building' AS name UNION ALL SELECT 'Ford Hall' UNION ALL SELECT 'Hill Hall' UNION ALL SELECT 'King Hall' UNION ALL SELECT 'Mark Jefferson Science Complex' UNION ALL SELECT 'Marshall Building' UNION ALL SELECT 'McKenny Hall' UNION ALL SELECT 'Porter Building' UNION ALL SELECT 'Pray-Harrold' UNION ALL SELECT 'Rackham Building' UNION ALL SELECT 'Roosevelt Hall' UNION ALL SELECT 'Sill Hall' UNION ALL SELECT 'Strong Hall') b
WHERE NOT EXISTS (SELECT 1 FROM map_item m WHERE m.discr = 'building' AND m.name = b.name);
SELECT 'advisor_programs' AS legacy_table, COUNT(*) AS row_count, MAX(updated_at) AS last_updated FROM advisor_programs
UNION ALL SELECT 'uacdc_advisor_programs', COUNT(*), MAX(updated_at) FROM uacdc_advisor_programs;
